use vstd::prelude::*;

verus! {

/// Spec helper: value on the diagonal is 1.0, off-diagonal is 0.0.
pub fn diag_val(i: int, j: int) -> (result: f64)
    ensures
        (i == j ==> result == 1.0f64) &&
        (i != j ==> result == 0.0f64)
{
    if i == j { 1.0f64 } else { 0.0f64 }
}

/// Construct an n×n identity matrix of f64.
pub fn identity(n: usize) -> (result: Vec<Vec<f64>>)
    ensures
        result.len() == n,
        forall|i: int|
            0 <= i < n as int ==>
                #[trigger] result[i].len() == n,
        forall|i: int, j: int|
            0 <= i < n as int && 0 <= j < n as int ==>
                #[trigger] result[i][j] == diag_val(i, j),
{
    let mut res: Vec<Vec<f64>> = Vec::new();

    let mut i: usize = 0;
    while i < n
        invariant
            res.len() == i,
            forall|ii: int|
                0 <= ii < i as int ==>
                    #[trigger] res[ii].len() == n,
            forall|ii: int, jj: int|
                0 <= ii < i as int && 0 <= jj < n as int ==>
                    #[trigger] res[ii][jj] == diag_val(ii, jj),
    {
        let mut row: Vec<f64> = Vec::new();

        let mut j: usize = 0;
        while j < n
            invariant
                row.len() == j,
                forall|jj: int|
                    0 <= jj < j as int ==>
                        #[trigger] row[jj] == diag_val(i as int, jj),
        {
            row.push(diag_val(i as int, j as int));
            j += 1;
        }

        res.push(row);
        i += 1;
    }

    res
}

} // verus!